-- K-9 ext — «대장 밖» 수식 결함 8종 성분 25행 (적용: MCP apply_migration k9_ext_policy_constants_2026_09_17)
-- 원문: 국가법령정보센터 DRF eflaw «시행일이 오늘 이전인 최신 판»(lawService target=eflaw, MST+그 판의 시행일자) 직접 대조 2026-09-17.
--   주택임대차보호법 MST 276291(2026-01-02) · 시행령 MST 287183(2026-07-01)
--   산업재해보상보험법 MST 283459(2026-07-01) · 소득세법 MST 280405(2026-07-01)·285523(법률 21548, 2026-04-21) — §59의2·§59의3·§104 두 판 동일
--   공무원보수규정 MST 288433(2026-08-01; 2026-12-03 시행예정 판 병 봉급 동일)
--   행정규칙(target=admrul): 고용노동부고시 제2025-47호(ID 2100000262710) · 제2026-60호(ID 2100000283564) 첨부 원문 PDF
--   한국은행 기준금리: bok.or.kr 기준금리 추이 표(2026-08-27 3.00% 변경) — 공시값이라 변경 시 이 행을 갱신해야 한다
-- 재사용(새로 만들지 않음): 증여 inh_rate_*·gift_* (k9 inh) · 양도 cgt_ltd_t1_*·cgt_basic_deduction·cgt_local_ratio (k9 cgt)
-- ⚠️ 접두 LIKE 충돌 사전 실측: key LIKE 'ext%' → 기존 0행(2026-09-17). schema_migrations 에 k9_ext 이력 0.
-- 파서 밖 값(장해 일수·주 15시간·나이 기준·60일)은 코드 상수 EXT_LAW(src/lib/calc/k9/ext.ts).

DO $$
DECLARE n_ext int;
BEGIN
  SELECT count(*) INTO n_ext FROM policy_constants WHERE key LIKE 'ext\_%';
  IF n_ext <> 25 THEN
    RAISE EXCEPTION 'k9 ext 행 수 불일치: ext %', n_ext;
  END IF;
END $$;
